input.code:
const out=[];
for (const id of [1,2,4]) {
  await browser.goto(`/product?id=${id}`);
  const d = await tools.get_product();
  const a = await tools.add_to_cart({quantity:1});
  out.push({d,a});
}
await tools.back_to_search();
out.push(await tools.cart_size());
return out;

